const http = require("http");
function fetchChunks(url, label) {
  return new Promise((resolve) => {
    const start = Date.now();
    http.get(url, (res) => {
      res.on("data", (chunk) => {
        const elapsed = Date.now() - start;
        const str = chunk.toString();
        const hasLamp = str.includes("Stone vase"); // checking vase
        const hasRelated = str.includes("Brass lamp");
        const hasShell = str.includes("Signal Shop collection");
        if (hasLamp || hasRelated || hasShell) {
          console.log(`[${label} +${elapsed}ms] shell=${hasShell} vase=${hasLamp} related=${hasRelated}`);
        }
      });
      res.on("end", resolve);
    });
  });
}
async function run() {
  console.log("--- First request (uncached) ---");
  await fetchChunks("http://localhost:3005/products/vase?currency=EUR", "Req 1");
  console.log("--- Second request (cached) ---");
  await fetchChunks("http://localhost:3005/products/vase?currency=EUR", "Req 2");
}
run();
'
